#include <vector>
#include <complex>
#include <algorithm>
#include <cmath>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const int n = static_cast<int>(x.size());
    if (n < 2) return;

    // Parallel stable mergesort:
    // 1) Split into blocks, sort each block in parallel.
    // 2) Iteratively merge adjacent blocks; at each merge pass, merges are independent and parallelizable.

    int max_threads = 1;
#pragma omp parallel
    {
#pragma omp single
        max_threads = omp_get_num_threads();
    }

    // Choose a block size that keeps work per block reasonable.
    // Ensure at least one element per block and not too many blocks.
    int block_size = std::max(1024, n / std::max(1, 4 * max_threads));
    block_size = std::max(1, block_size);

    auto mag2 = [](const std::complex<double>& a) -> double {
        // Use squared magnitude to avoid sqrt and keep ordering consistent.
        const double re = a.real();
        const double im = a.imag();
        return re * re + im * im;
    };

    auto cmp = [&](const std::complex<double>& a, const std::complex<double>& b) -> bool {
        const double ma = mag2(a);
        const double mb = mag2(b);
        if (ma < mb) return true;
        if (ma > mb) return false;
        // Tie-breaker for deterministic ordering (not required by problem, but helps reproducibility)
        if (a.real() < b.real()) return true;
        if (a.real() > b.real()) return false;
        return a.imag() < b.imag();
    };

    // Temporary buffer for merges (single shared vector; merges write into disjoint ranges).
    std::vector<std::complex<double>> tmp(x.size());

    // Phase 1: sort blocks in parallel
#pragma omp parallel for schedule(static)
    for (int start = 0; start < n; start += block_size) {
        int end = std::min(n, start + block_size);
        std::stable_sort(x.begin() + start, x.begin() + end, cmp);
    }

    // Phase 2: merge blocks; alternate between x and tmp each pass
    bool in_x = true;
    for (int width = block_size; width < n; width *= 2) {
        auto &src = in_x ? x : tmp;
        auto &dst = in_x ? tmp : x;

#pragma omp parallel for schedule(static)
        for (int start = 0; start < n; start += 2 * width) {
            const int mid = std::min(n, start + width);
            const int end = std::min(n, start + 2 * width);

            if (mid >= end) {
                // Only left run exists; copy it
                std::copy(src.begin() + start, src.begin() + end, dst.begin() + start);
            } else {
                std::merge(src.begin() + start, src.begin() + mid,
                           src.begin() + mid,   src.begin() + end,
                           dst.begin() + start, cmp);
            }
        }

        in_x = !in_x;
    }

    // If final data ended up in tmp, copy back
    if (!in_x) {
        x.swap(tmp);
    }
}
